<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_permission('PRESUPUESTO_ASIGNAR');if(!user_has_any_role($user,['ADMIN','PRESIDENTE']))json_response(['ok'=>false,'error'=>'Solo Administración o Presidencia pueden asignar presupuesto'],403);$in=json_input();$dep=(int)($in['departamento_id']??0);$year=(int)($in['ejercicio']??date('Y'));$amount=money_value($in['presupuesto_asignado']??0);$obs=trim((string)($in['observaciones']??''));if($dep<=0||$year<2020||$year>2100||$amount<0)json_response(['ok'=>false,'error'=>'Datos de presupuesto inválidos'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);if(!user_is_global($user)&&!in_array($dep,visible_department_ids($db,$user),true)){$db->close();json_response(['ok'=>false,'error'=>'No puedes asignar presupuesto a ese departamento'],403);}$before=department_balance($db,$dep,$year);$uid=(int)$user['user_id'];$st=$db->prepare("INSERT INTO presupuesto_departamento(departamento_id,ejercicio,presupuesto_asignado,observaciones,estatus,created_by_usuario_id,updated_by_usuario_id) VALUES(?,?,?,?, 'ACTIVO',?,?) ON DUPLICATE KEY UPDATE presupuesto_asignado=VALUES(presupuesto_asignado),observaciones=VALUES(observaciones),estatus='ACTIVO',updated_by_usuario_id=VALUES(updated_by_usuario_id),updated_at=NOW()");$st->bind_param('iidsii',$dep,$year,$amount,$obs,$uid,$uid);$st->execute();$st->close();$after=department_balance($db,$dep,$year);audit_log($db,$uid,'PRESUPUESTO_ASIGNAR','PRESUPUESTO',$dep.'-'.$year,'Asignación presupuestal',$before,$after);$db->close();json_response(['ok'=>true,'data'=>$after]);
